import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.nkraVhM_.js";var i=JSON.parse(`{"title":"使用指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/usage.md","filePath":"zh-CN/guide/usage.md","lastUpdated":1793173149000}`),a={name:`zh-CN/guide/usage.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="使用指南" tabindex="-1">使用指南 <a class="header-anchor" href="#使用指南" aria-label="Permalink to “使用指南”">​</a></h1><h2 id="基础玩法" tabindex="-1">基础玩法 <a class="header-anchor" href="#基础玩法" aria-label="Permalink to “基础玩法”">​</a></h2><h3 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to “目标”">​</a></h3><p>填满 9×9 的网格，使每一<strong>行</strong>、每一<strong>列</strong>以及九个 3×3 的<strong>宫</strong>中都恰好包含 1 到 9 的所有数字各一次。任何单元内都不允许重复。</p><h3 id="如何游玩" tabindex="-1">如何游玩 <a class="header-anchor" href="#如何游玩" aria-label="Permalink to “如何游玩”">​</a></h3><ul><li><strong>填入数字</strong>：点按或点击一个空格，然后点按屏幕底部数字键盘上的数字。</li><li><strong>铅笔笔记（候选数）</strong>：开启铅笔模式，然后点按格子写下小号的候选数字。在追踪各种可能性时很有用。</li><li><strong>擦除</strong>：点按“擦除”按钮清除格中的数字（在铅笔模式下则清除铅笔标记）。</li><li><strong>提示</strong>：点按“提示”，揭示一个正确格子的数字。</li><li><strong>撤销</strong>：点按“撤销”回退上一步（支持完整的撤销历史）。</li></ul><h3 id="难度级别" tabindex="-1">难度级别 <a class="header-anchor" href="#难度级别" aria-label="Permalink to “难度级别”">​</a></h3><p>难度级别决定了开局时有多少格是预先填好的（已知格）：</p><table tabindex="0"><thead><tr><th>级别</th><th>已知格</th><th>适合人群</th></tr></thead><tbody><tr><td>简单</td><td>45</td><td>新手与快速来一局</td></tr><tr><td>中等</td><td>36</td><td>休闲玩家</td></tr><tr><td>困难</td><td>31</td><td>经常解题的玩家</td></tr><tr><td>专家</td><td>27</td><td>有经验的玩家</td></tr><tr><td>大师</td><td>24</td><td>解谜高手</td></tr></tbody></table><p><img src="/screenshot-mac-main.png" alt="Mac 上的数独棋盘"></p><h2 id="游戏操作" tabindex="-1">游戏操作 <a class="header-anchor" href="#游戏操作" aria-label="Permalink to “游戏操作”">​</a></h2><h3 id="iphone-ipad" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ul><li><strong>点按</strong>空格将其选中</li><li><strong>点按数字</strong>键盘上的数字完成填入</li><li><strong>切换铅笔模式</strong>以写入或擦除候选笔记</li><li><strong>使用擦除</strong>清空格中的内容</li><li><strong>使用提示</strong>在卡住时获得帮助</li><li><strong>使用撤销</strong>回退操作</li></ul><h3 id="mac" tabindex="-1">Mac <a class="header-anchor" href="#mac" aria-label="Permalink to “Mac”">​</a></h3><ul><li><strong>左键点击</strong>空格将其选中</li><li><strong>按下数字键（1–9）</strong> 或点击屏幕数字键盘完成填入</li><li><strong>切换铅笔模式</strong>以记录候选笔记</li><li><strong>键盘快捷键</strong>： <ul><li><code>⌘N</code> —— 新游戏</li><li><code>⌘Z</code> —— 撤销</li><li><code>⌘1</code> 到 <code>⌘5</code> —— 以对应难度开始新游戏</li></ul></li></ul><p><img src="/screenshot-iphone-main.png" alt="iPhone 上的 Sudoku 主界面"></p><p><img src="/screenshot-ipad-main.png" alt="iPad 上的 Sudoku 主界面"></p><h2 id="智能功能" tabindex="-1">智能功能 <a class="header-anchor" href="#智能功能" aria-label="Permalink to “智能功能”">​</a></h2><h3 id="铅笔笔记系统" tabindex="-1">铅笔笔记系统 <a class="header-anchor" href="#铅笔笔记系统" aria-label="Permalink to “铅笔笔记系统”">​</a></h3><p>开启铅笔模式后，你可以在空格中写下小号的候选数字。智能铅笔系统会：</p><ul><li><strong>自动清除关联格的铅笔标记</strong>：当你填入一个确定的数字后，同行、同列和同宫中该数字的铅笔标记会自动移除。</li><li><strong>逐格切换</strong>：随时可以在填数模式和铅笔模式之间切换。</li></ul><h3 id="错误检查" tabindex="-1">错误检查 <a class="header-anchor" href="#错误检查" aria-label="Permalink to “错误检查”">​</a></h3><p>可选的错误高亮会用红色标出填错的数字，帮助你在不破坏解题乐趣的前提下学习。</p><h3 id="每日挑战" tabindex="-1">每日挑战 <a class="header-anchor" href="#每日挑战" aria-label="Permalink to “每日挑战”">​</a></h3><p>每天都会生成一道全新的大师级题目。每日挑战的进度会在统计中记录，并以日历视图显示你的连续天数。</p><h3 id="统计" tabindex="-1">统计 <a class="header-anchor" href="#统计" aria-label="Permalink to “统计”">​</a></h3><p>追踪你的数独之旅：</p><ul><li>总局数与胜率</li><li>当前连续天数与最长连续天数</li><li>按难度细分：通关局数、最佳用时、平均用时</li><li>标有完成状态的每日挑战日历</li></ul><p><img src="/screenshot-mac-settings.png" alt="Mac 上的 Sudoku 统计"></p><h2 id="主题" tabindex="-1">主题 <a class="header-anchor" href="#主题" aria-label="Permalink to “主题”">​</a></h2><p>在设置中挑选八种精美的配色主题：</p><table tabindex="0"><thead><tr><th>主题</th><th>风格</th></tr></thead><tbody><tr><td>经典</td><td>干净的白色搭配蓝色点缀</td></tr><tr><td>午夜</td><td>深蓝调的深色模式</td></tr><tr><td>纸张</td><td>温暖的羊皮纸质感</td></tr><tr><td>森林</td><td>自然的绿色</td></tr><tr><td>海洋</td><td>宁静的海蓝色</td></tr><tr><td>日落</td><td>温暖的橙色渐变</td></tr><tr><td>薰衣草</td><td>柔和的紫色调</td></tr><tr><td>玫瑰</td><td>优雅的粉色系</td></tr></tbody></table><h2 id="icloud-同步" tabindex="-1">iCloud 同步 <a class="header-anchor" href="#icloud-同步" aria-label="Permalink to “iCloud 同步”">​</a></h2><p>当你的设备已登录 iCloud 时：</p><ul><li>游戏存档会自动同步——可在任意设备上继续</li><li>统计数据与设置保持同步</li><li>每日挑战进度可在设备间转移</li><li>需要 iOS/iPadOS 16+ 或 macOS 15+</li></ul><h2 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h2><p>连接 Game Center 后可以：</p><ul><li>在<strong>排行榜</strong>上按难度比拼最佳完成时间</li><li>赢取<strong>成就</strong>：首次通关、简单/中等/困难/专家/大师通关、完美通关（不使用提示且不出现错误）</li></ul><h2 id="打印题目-mac" tabindex="-1">打印题目（Mac） <a class="header-anchor" href="#打印题目-mac" aria-label="Permalink to “打印题目（Mac）”">​</a></h2><p>在 Mac 上可以直接从应用中打印题目：</p><ol><li>从工具栏打开 <strong>打印</strong> 对话框</li><li>选择难度级别（从简单到大师）</li><li>根据需要开启“包含答案”</li><li>点按 <strong>打印</strong></li></ol><p>非常适合用纸笔线下解题！</p><h2 id="音效" tabindex="-1">音效 <a class="header-anchor" href="#音效" aria-label="Permalink to “音效”">​</a></h2><p>Sudoku 提供细腻的音效：</p><ul><li>落子确认</li><li>提示揭示</li><li>错误提醒</li><li>胜利庆祝</li></ul><p>可在 <strong>设置 → 声音</strong> 中开关音效。</p><h2 id="技巧与窍门" tabindex="-1">技巧与窍门 <a class="header-anchor" href="#技巧与窍门" aria-label="Permalink to “技巧与窍门”">​</a></h2><ul><li><strong>从已知条件入手</strong>——先扫描已经填了不少数字的行、列和宫。</li><li><strong>善用铅笔笔记</strong>——在困难、专家和大师难度下尤其有用。</li><li><strong>寻找唯一候选数</strong>——如果某个格子只剩一个可能的候选数，就填上它。</li><li><strong>寻找隐性唯一数</strong>——如果某个数字在某行/某列/某宫内只能放在一个位置，就填在那里。</li><li><strong>少用提示</strong>——提示很适合学习，但不用提示完成一道题会更有成就感。</li><li><strong>积累每日连续天数</strong>——每日挑战是保持练习习惯的好方式。</li></ul>`,48)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};